      "ballot_id": "B016",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall prediction and its experimental realization established topological insulators as a major new class of quantum matter, with broad influence across condensed-matter physics.",
        "attribution": "Kane and Mele supplied the foundational theory, and Molenkamp's experiments established the quantum spin Hall effect in a material system. The later three-dimensional topological-insulator work involved a wider community, so the prize scope should be defined carefully.",
        "maturity": "Theoretical foundations and experimental signatures have been repeatedly confirmed over many years.",
        "uncertainties": [
          "The candidate combines related but distinct discoveries, making the boundary of the contribution and credit difficult to specify."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene revealed tunable correlated states in a two-dimensional material and opened a highly productive field of moiré quantum materials.",
        "attribution": "Bistritzer and MacDonald predicted the special flat-band regime; Jarillo-Herrero's group demonstrated its striking correlated behavior. The theory and experiment form a coherent contribution.",
        "maturity": "The central phenomenon has been reproduced in multiple devices and related moiré systems, though the detailed phase diagram remains under active study.",
        "uncertainties": [
          "The microscopic origins of several observed phases and their relation to superconductivity remain unsettled."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electron systems quantitatively tractable and became a central framework for understanding materials where conventional band theory fails.",
        "attribution": "These three made defining contributions to the formulation and development of the method. The broader development involved a substantial community, so credit should reflect the specific foundational advances.",
        "maturity": "The framework has been established for decades, extensively developed, and applied alongside experiment to many material classes.",
        "uncertainties": [
          "Its impact is chiefly methodological and theoretical, and the precise division of credit across the early development is not simple."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B018",
      "proposed_laureates": [
        "John J. Croat",
        "Masato Sagawa"
      ],
      "assessment": {
        "nobel_worthiness": "Neodymium-iron-boron magnets are a major materials discovery with exceptional magnetic performance and lasting importance in motors, generators, and many technologies.",
        "attribution": "Croat and Sagawa independently developed the material in separate industrial research efforts, making the proposed joint attribution compelling.",
        "maturity": "The material and its applications have been thoroughly validated over several decades.",
        "uncertainties": [
          "The discovery is old and its industrial development involved additional researchers and engineering contributions."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics demonstrated strong, controllable interaction between microwave photons and superconducting qubits, enabling major advances in quantum measurement and information processing.",
        "attribution": "Blais provided key theoretical proposals, while Wallraff and Schoelkopf led landmark experimental demonstrations and platform development.",
        "maturity": "The core effects have been reproduced and developed into a mature experimental platform, with continuing progress in scaling and error correction.",
        "uncertainties": [
          "The field's development is broad, and a sharply bounded discovery and allocation of credit require care."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Shinji Yuasa",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Large tunnel magnetoresistance in practical magnetic tunnel junctions enabled important spintronic devices and gave a clear route to read magnetic states electrically.",
        "attribution": "Moodera and the groups of Yuasa and Miyazaki made influential independent advances in junction materials and performance; the exact scope should distinguish this from giant magnetoresistance.",
        "maturity": "The effect is robust, reproducible, and foundational to mature device technologies.",
        "uncertainties": [
          "The nominated discovery is closely related to, but distinct from, giant magnetoresistance, which already received a Nobel Prize."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Franz J. Giessibl",
        "Gerhard Meyer",
        "Leo Gross"
      ],
      "assessment": {
        "nobel_worthiness": "Atomic-resolution force microscopy enabled direct imaging and manipulation of individual atoms and molecular structures, substantially extending what scanning probes can reveal.",
        "attribution": "Giessibl's qPlus sensor innovation and the subsequent work of Meyer and Gross on atomic-scale imaging provide a credible sequence of key contributions.",
        "maturity": "The technique has been independently adopted and refined, with many demonstrations across surfaces and molecular systems.",
        "uncertainties": [
          "The discovery encompasses both sensor development and later imaging advances, and the attribution boundary is not entirely clear."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Christian Pfleiderer",
        "Roland Wiesendanger",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetic skyrmions established nanoscale topological spin textures as real, controllable excitations and stimulated extensive research in magnetism and spintronics.",
        "attribution": "Pfleiderer, Wiesendanger, and Tokura contributed important complementary demonstrations and characterization, but the field's theoretical and experimental origins are distributed across several groups.",
        "maturity": "Skyrmions have been observed in multiple materials and by different techniques, though practical device control remains an active research challenge.",
        "uncertainties": [
          "The candidate spans prediction, observation, and later materials discoveries, so a precise Nobel-sized contribution and credit division are uncertain."
        ]
      }
    }
  ]
